import JSON

"""
	gen( x, name )

Generate fixture data and write to file.

# Arguments

* `x`: domain
* `name::AbstractString`: output filename

# Examples

``` julia
julia> x = range( -100, stop = 100, length = 503 );
julia> gen( x, "data.json" );
```
"""
function gen( x, name )
	y = Array{Any}( undef, length(x) );
	z = Array{Any}( undef, length(x) );
	for i in eachindex(x)
		# Convert to Float16, then get bit representation
		f16 = convert( Float16, x[i] );
		# Get binary string (16 bits for Float16)
		bits = bitstring( f16 );
		y[i] = bits;
		# Store the expected value (converting back to Float64 for JSON)
		z[i] = convert( Float64, f16 );
	end

	# Store data to be written to file as a collection:
	data = Dict([
		("x", y),
		("expected", z)
	]);

	# Based on the script directory, create an output filepath:
	filepath = joinpath( dir, name );

	# Write the data to the output filepath as JSON:
	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# Small values (subnormal range for float16):
x = range( 1e-6, stop = 1e-8, length = 503 );
gen( x, "bits_1e-6_1e-8.json" );

# Medium values (typical float16 range):
x = range( -100, stop = 100, length = 503 );
gen( x, "bits_-100_100.json" );

# Large values (approaching float16 max ~65504):
x = range( 1e2, stop = 6e4, length = 503 );
gen( x, "bits_1e2_6e4.json" );

# Very small subnormal values:
x = range( 1e-7, stop = 1e-9, length = 503 );
gen( x, "bits_1e-7_1e-9.json" );
